package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 1000000007

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n, k int
	fmt.Fscan(reader, &n, &k)

	fact := make([]int64, n+1)
	invFact := make([]int64, n+1)
	fact[0] = 1
	for i := 1; i <= n; i++ {
		fact[i] = fact[i-1] * int64(i) % MOD
	}

	// Fermat's little theorem for modular inverse
	invFact[n] = modPow(fact[n], MOD-2)
	for i := n; i >= 1; i-- {
		invFact[i-1] = invFact[i] * int64(i) % MOD
	}

	// dp[i] = number of valid permutations of length i
	dp := make([]int64, n+1)
	dp[0] = 1

	// prefix sum of dp[i] * invFact[i]
	pref := make([]int64, n+1)
	pref[0] = 1 // dp[0] * invFact[0]

	for i := 1; i <= n; i++ {
		// sum_{j = max(0, i-k)}^{i-1} dp[j] * invFact[j]
		l := i - k
		if l < 0 {
			l = 0
		}
		r := i - 1

		var sum int64
		if l == 0 {
			sum = pref[r]
		} else {
			sum = (pref[r] - pref[l-1] + MOD) % MOD
		}

		dp[i] = fact[i-1] * sum % MOD
		pref[i] = (pref[i-1] + dp[i]*invFact[i]) % MOD
	}

	ans := (fact[n] - dp[n] + MOD) % MOD
	fmt.Println(ans)
}

func modPow(a, e int64) int64 {
	res := int64(1)
	a %= MOD
	for e > 0 {
		if e&1 == 1 {
			res = res * a % MOD
		}
		a = a * a % MOD
		e >>= 1
	}
	return res
}
